import { Box, Stack, Typography } from '@mui/material'
import { useEffect, useRef } from 'react'
import type { ActionRunHistoryEntry } from '../../data/electron_action_bridge'
import { dialogService } from '../../services/dialog_service'
import { CommitReferenceRow } from './commit_reference_row'

interface HistoryEntryRowProps {
    entry: ActionRunHistoryEntry
}

interface ActionRunHistoryProps {
    compact?: boolean
    entries: ActionRunHistoryEntry[]
    error: string | null
}

/** One run history line with commits produced across its action chain. */
function HistoryEntryRow(props: HistoryEntryRowProps) {
    const { entry } = props
    const agentLabel = entry.agent
        ? ` (${entry.agent}${entry.model ? ` / ${entry.model}` : ''}${entry.thinkingLevel ? ` / ${entry.thinkingLevel}` : ''})`
        : ''

    return (
        <Box>
            <Typography color="text.secondary" variant="caption">
                {entry.status}{agentLabel}: {entry.output || entry.prompt}
            </Typography>
            {entry.commits?.map((commitReference) => (
                <CommitReferenceRow
                    commitReference={commitReference}
                    key={`${commitReference.repositoryRoot}-${commitReference.commit}`}
                />
            ))}
        </Box>
    )
}

/** Presentation-only list of previous action runs. */
export function ActionRunHistory(props: ActionRunHistoryProps) {
    const { compact = false, entries, error } = props
    const reportedErrorRef = useRef<string | null>(null)

    useEffect(() => {
        if (!error) {
            reportedErrorRef.current = null

            return
        }

        if (error === reportedErrorRef.current) return

        dialogService.error(error)
        reportedErrorRef.current = error
    }, [error])

    if (entries.length === 0) return null

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: compact ? 1 : 0 }}>
            <Typography color="text.secondary" sx={compact ? { fontSize: 12, fontWeight: 600 } : undefined} variant="caption">
                Run history
            </Typography>
            {error ? (
                <Typography color="text.secondary" variant="caption">
                    Run history unavailable.
                </Typography>
            ) : null}
            <Stack spacing={0.5} sx={{ mt: 0.5 }}>
                {entries.map((entry, index) => (
                    <HistoryEntryRow entry={entry} key={`${entry.completedAt}-${entry.status}-${index}`} />
                ))}
            </Stack>
        </Box>
    )
}

import { Box, Stack, Typography } from '@mui/material'
import type { ActionRunLogEntry } from '../../data/action_run_types'
import { actionStatusLabel } from './action_status'

interface ActionRunStatusProps {
    color: string
    logs: ActionRunLogEntry[]
    status: string
}

/** Presentation-only current run status and log summary. */
export function ActionRunStatus(props: ActionRunStatusProps) {
    const { color, logs, status } = props

    return (
        <Box role="status">
            <Typography color={color} variant="body2">
                {actionStatusLabel(status as ActionRunLogEntry['status'])}
            </Typography>
            {logs.length > 0 ? (
                <Stack spacing={0.5} sx={{ mt: 1 }}>
                    {logs.map((log, index) => (
                        <Typography key={`${log.actionName}-${log.phase}-${index}`} color="text.secondary" variant="caption">
                            {log.phase}: {log.message}{log.stdout || log.stderr ? ` â€” ${log.stdout}${log.stderr}` : ''}
                            {log.thinkingLevel ? ` (thinking: ${log.thinkingLevel})` : ''}
                        </Typography>
                    ))}
                </Stack>
            ) : null}
        </Box>
    )
}

